package candidate

import (
	"errors"
	"math"
	"net/http"
	"strconv"
	"strings"
	"time"
)

// ParseRetryAfter parses an HTTP Retry-After header value, relative to now.
// It accepts a nonnegative decimal integer number of seconds, or an HTTP
// date in a format accepted by http.ParseTime. A past date yields zero.
func ParseRetryAfter(value string, now time.Time) (time.Duration, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return 0, errors.New("empty Retry-After value")
	}

	// Try a nonnegative decimal integer number of seconds.
	if !strings.ContainsAny(value, ".eE+-") {
		if i, err := strconv.ParseInt(value, 10, 64); err == nil {
			if i < 0 {
				return 0, err
			}
			if i > int64(math.MaxInt64/time.Second) {
				return 0, err
			}
			d := time.Duration(i) * time.Second
			if d < 0 || d/time.Second != i {
				return 0, err
			}
			return d, nil
		}
	}

	t, err := http.ParseTime(value)
	if err != nil {
		return 0, err
	}

	d := t.Sub(now)
	if d <= 0 {
		return 0, nil
	}
	if d > time.Duration(math.MaxInt64) {
		return 0, errors.New("Retry-After duration overflows time.Duration")
	}
	return d, nil
}

